 arcade:function(s){var gs=GAMES.filter(function(g){return g.on!==false&&g.on!=='0'});return'<section class="arcade-s"><div class="w">'+secHead(s)+'<div class="gstrip">'+gs.map(function(g,i){return'<a class="card gm tilt rv" style="--d:'+(i*.06)+'s" href="#/play/'+E(g.id)+'"><span class="gico">'+E(g.icon)+'</span><h3>'+E(g.t)+'</h3><p>'+E(g.d)+'</p><div class="gmeta"><span>'+E(g.diff||'')+'</span><span>+'+(+g.xp||0)+' XP</span></div></a>'}).join('')+'</div>'+(s.btn?'<div class="c" style="margin-top:34px"><a class="btn pri" href="'+E(safeLink(s.link))+'">'+E(s.btn)+'</a></div>':'')+'</div></section>'},
