 features:function(s){return'<section class="tight"><div class="w">'+secHead(s)+'<div class="gA g3">'+(s.items||[]).map(function(it,i){return'<div class="card tilt rv" style="--d:'+(i*.07)+'s"><div class="ic">'+E(it.i)+'</div><h3>'+E(it.t)+'</h3><p>'+E(it.p)+'</p></div>'}).join('')+'</div></div></section>'},
